changeSet.sql:
ALTER TABLE zc_care_plan
  ADD CONSTRAINT fk_zc_care_plan_tenant FOREIGN KEY (tenant_id) REFERENCES zc_tenant (id);
-- Plan version must match the enrolment's version.
ALTER TABLE zc_care_plan
  ADD CONSTRAINT fk_zc_care_plan_enrolment FOREIGN KEY (tenant_id, enrolment_id, programme_version_id)
    REFERENCES zc_enrolment (tenant_id, id, programme_version_id);
ALTER TABLE zc_care_plan
  ADD CONSTRAINT fk_zc_care_plan_programme_version FOREIGN KEY (tenant_id, programme_version_id)
    REFERENCES zc_programme_version (tenant_id, id);
ALTER TABLE zc_care_plan
  ADD CONSTRAINT fk_zc_care_plan_supersedes FOREIGN KEY (tenant_id, supersedes_plan_id, enrolment_id)
    REFERENCES zc_care_plan (tenant_id, id, enrolment_id);

ALTER TABLE zc_goal
  ADD CONSTRAINT fk_zc_goal_tenant FOREIGN KEY (tenant_id) REFERENCES zc_tenant (id);
-- Goal type must match the plan's programme version.
ALTER TABLE zc_goal
  ADD CONSTRAINT fk_zc_goal_care_plan FOREIGN KEY (tenant_id, care_plan_id, programme_version_id)
    REFERENCES zc_care_plan (tenant_id, id, programme_version_id);
ALTER TABLE zc_goal
  ADD CONSTRAINT fk_zc_goal_goal_type FOREIGN KEY (tenant_id, goal_type_id, programme_version_id)
    REFERENCES zc_goal_type (tenant_id, id, programme_version_id);

ALTER TABLE zc_intervention
  ADD CONSTRAINT fk_zc_intervention_tenant FOREIGN KEY (tenant_id) REFERENCES zc_tenant (id);
ALTER TABLE zc_intervention
  ADD CONSTRAINT fk_zc_intervention_care_plan FOREIGN KEY (tenant_id, care_plan_id)
    REFERENCES zc_care_plan (tenant_id, id);
-- Goal must be in the same plan.
ALTER TABLE zc_intervention
  ADD CONSTRAINT fk_zc_intervention_goal FOREIGN KEY (tenant_id, goal_id, care_plan_id)
    REFERENCES zc_goal (tenant_id, id, care_plan_id);

ALTER TABLE zc_care_plan_link
  ADD CONSTRAINT fk_zc_care_plan_link_tenant FOREIGN KEY (tenant_id) REFERENCES zc_tenant (id);
ALTER TABLE zc_care_plan_link
  ADD CONSTRAINT fk_zc_care_plan_link_care_plan FOREIGN KEY (tenant_id, care_plan_id)
    REFERENCES zc_care_plan (tenant_id, id);

ALTER TABLE zc_plan_review
  ADD CONSTRAINT fk_zc_plan_review_tenant FOREIGN KEY (tenant_id) REFERENCES zc_tenant (id);
ALTER TABLE zc_plan_review
  ADD CONSTRAINT fk_zc_plan_review_care_plan FOREIGN KEY (tenant_id, care_plan_id)
    REFERENCES zc_care_plan (tenant_id, id);

-- Care plan approval can't be changed once set.
CREATE FUNCTION zc_care_plan_approval_immutable() RETURNS trigger
  LANGUAGE plpgsql
AS $fn$
BEGIN
  IF OLD.approved_at IS NOT NULL
     AND (NEW.approved_by IS DISTINCT FROM OLD.approved_by
          OR NEW.approved_at IS DISTINCT FROM OLD.approved_at) THEN
    RAISE EXCEPTION 'trg_zc_care_plan_approval_immutable: the recorded approval of care plan % cannot be rewritten', OLD.id
      USING ERRCODE = 'integrity_constraint_violation',
            CONSTRAINT = 'trg_zc_care_plan_approval_immutable', TABLE = TG_TABLE_NAME;
  END IF;
  IF OLD.activated_at IS NOT NULL AND NEW.activated_at IS DISTINCT FROM OLD.activated_at THEN
    RAISE EXCEPTION 'trg_zc_care_plan_approval_immutable: activated_at of care plan % cannot be rewritten', OLD.id
      USING ERRCODE = 'integrity_constraint_violation',
            CONSTRAINT = 'trg_zc_care_plan_approval_immutable', TABLE = TG_TABLE_NAME;
  END IF;
  RETURN NEW;
END
$fn$;

CREATE TRIGGER trg_zc_care_plan_approval_immutable
  BEFORE UPDATE ON zc_care_plan
  FOR EACH ROW EXECUTE FUNCTION zc_care_plan_approval_immutable();
CREATE TRIGGER trg_zc_care_plan_pins
  BEFORE UPDATE ON zc_care_plan
  FOR EACH ROW EXECUTE FUNCTION zc_forbid_pinned_change(
    'trg_zc_care_plan_pins', 'enrolment_id', 'programme_version_id', 'supersedes_plan_id', 'version_number');
CREATE TRIGGER trg_zc_care_plan_touch BEFORE UPDATE ON zc_care_plan FOR EACH ROW EXECUTE FUNCTION zc_touch_row();

rollback.sql:
DROP TRIGGER trg_zc_care_plan_approval_immutable ON zc_care_plan;
DROP TRIGGER trg_zc_care_plan_pins ON zc_care_plan;
DROP TRIGGER trg_zc_care_plan_touch ON zc_care_plan;
DROP FUNCTION zc_care_plan_approval_immutable();

changeSet.sql:
-- Tenant isolation. The app must connect as zc_app: superusers bypass RLS.
ALTER TABLE zc_care_plan ENABLE ROW LEVEL SECURITY;
ALTER TABLE zc_care_plan FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_zc_care_plan_tenant ON zc_care_plan
  USING (tenant_id = zc_current_tenant())
  WITH CHECK (tenant_id = zc_current_tenant());
ALTER TABLE zc_goal ENABLE ROW LEVEL SECURITY;
ALTER TABLE zc_goal FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_zc_goal_tenant ON zc_goal
  USING (tenant_id = zc_current_tenant())
  WITH CHECK (tenant_id = zc_current_tenant());
ALTER TABLE zc_intervention ENABLE ROW LEVEL SECURITY;
ALTER TABLE zc_intervention FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_zc_intervention_tenant ON zc_intervention
  USING (tenant_id = zc_current_tenant())
  WITH CHECK (tenant_id = zc_current_tenant());
ALTER TABLE zc_care_plan_link ENABLE ROW LEVEL SECURITY;
ALTER TABLE zc_care_plan_link FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_zc_care_plan_link_tenant ON zc_care_plan_link
  USING (tenant_id = zc_current_tenant())
  WITH CHECK (tenant_id = zc_current_tenant());
ALTER TABLE zc_plan_review ENABLE ROW LEVEL SECURITY;
ALTER TABLE zc_plan_review FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_zc_plan_review_tenant ON zc_plan_review
  USING (tenant_id = zc_current_tenant())
  WITH CHECK (tenant_id = zc_current_tenant());

rollback.sql:
DROP POLICY rls_zc_care_plan_tenant ON zc_care_plan;
ALTER TABLE zc_care_plan NO FORCE ROW LEVEL SECURITY;
ALTER TABLE zc_care_plan DISABLE ROW LEVEL SECURITY;
DROP POLICY rls_zc_goal_tenant ON zc_goal;
ALTER TABLE zc_goal NO FORCE ROW LEVEL SECURITY;
ALTER TABLE zc_goal DISABLE ROW LEVEL SECURITY;
DROP POLICY rls_zc_intervention_tenant ON zc_intervention;
ALTER TABLE zc_intervention NO FORCE ROW LEVEL SECURITY;
ALTER TABLE zc_intervention DISABLE ROW LEVEL SECURITY;
DROP POLICY rls_zc_care_plan_link_tenant ON zc_care_plan_link;
ALTER TABLE zc_care_plan_link NO FORCE ROW LEVEL SECURITY;
ALTER TABLE zc_care_plan_link DISABLE ROW LEVEL SECURITY;
DROP POLICY rls_zc_plan_review_tenant ON zc_plan_review;
ALTER TABLE zc_plan_review NO FORCE ROW LEVEL SECURITY;
ALTER TABLE zc_plan_review DISABLE ROW LEVEL SECURITY;

changeSet.sql:
GRANT SELECT, INSERT, UPDATE ON zc_care_plan TO zc_app;
GRANT USAGE ON SEQUENCE zc_care_plan_id_seq TO zc_app;
GRANT SELECT, INSERT, UPDATE ON zc_goal TO zc_app;
GRANT USAGE ON SEQUENCE zc_goal_id_seq TO zc_app;
GRANT SELECT, INSERT, UPDATE ON zc_intervention TO zc_app;
GRANT USAGE ON SEQUENCE zc_intervention_id_seq TO zc_app;
GRANT SELECT, INSERT, UPDATE ON zc_care_plan_link TO zc_app;
GRANT USAGE ON SEQUENCE zc_care_plan_link_id_seq TO zc_app;
GRANT SELECT, INSERT ON zc_plan_review TO zc_app;
REVOKE UPDATE, DELETE, TRUNCATE ON zc_plan_review FROM zc_app;
GRANT USAGE ON SEQUENCE zc_plan_review_id_seq TO zc_app;

